const cut1 = T1 + TOTAL1 / 2, cut2 = T2 + .6;   // 정해진 시각에 바로 바뀜
if (t >= cut1) draw(scene2);
if (t >= cut2) draw(scene3);

const SLATS = 8, TOTAL1 = 1.0, FLIP = .5;
const stag = (TOTAL1 - FLIP) / (SLATS - 1);
const ph = Math.PI / 2 * easeInOut(seg(t, T1 + i * stag, T1 + i * stag + FLIP));
const hh = slatH * Math.cos(ph);                      // 돌수록 얇아짐
ctx.drawImage(scene1, 0, i * slatH, W, slatH, 0, cy - hh / 2, W, hh);

const COLS = 10, GRAV = 900;
const u = Math.max(0, t - t0 - shard.delay);          // 이 조각이 날아간 시간
const x = cx + vx * u, y = cy + vy * u + .5 * GRAV * u * u;
ctx.translate(x, y); ctx.rotate(spin * u); ctx.translate(-cx, -cy);
ctx.clip(trianglePath); ctx.drawImage(scene2, 0, 0);
